export const supportedLocales = ["en","ja","ko","es","fr","de","pt","it","zh","vi"] as const;
export type LocaleCode = typeof supportedLocales[number];

export function normalizeLocale(value?: string | string[] | null): LocaleCode {
  const candidate = Array.isArray(value) ? value[0] : value;
  return supportedLocales.includes(candidate as LocaleCode) ? candidate as LocaleCode : "en";
}

export function withoutRecipient(value:string) {
  return value
    .replace(/\s*[,，、]\s*\{name\}/g, "")
    .replace(/\{name\}(?:さん|님|씨)?[、,，。！？]?\s*/g, "")
    .replace(/\s+([.!?。！？])/g, "$1")
    .trim();
}

