function mergeMessages(base: Messages, patch: Partial<Messages>): Messages {
  return {
    ...base,
    ...patch,
    header:{...base.header,...patch.header},
    home:{...base.home,...patch.home,steps:patch.home?.steps ?? base.home.steps,trust:patch.home?.trust ?? base.home.trust},
    studio:{
      ...base.studio,...patch.studio,
      occasions:{...base.studio.occasions,...patch.studio?.occasions},
      relations:{...base.studio.relations,...patch.studio?.relations},
      feelings:{...base.studio.feelings,...patch.studio?.feelings},
      copy:{...base.studio.copy,...patch.studio?.copy}
    }
  };
}

export function getMessages(locale: LocaleCode): Messages {
  return locale === "en" ? en : mergeMessages(en, overrides[locale]);
}

export function interpolate(value:string, vars:Record<string,string>) {
  return value.replace(/\{(\w+)\}/g,(_,key)=>vars[key] ?? "");
}
